// ===== Find Due Vaccinations =====
// Runs once a day. Works out who is due, skips anyone who has opted out, already booked,
// or already been reminded for this due date, and reports rows with dates it cannot read.
const CFG = $('Config').first().json;
// --- Google Sheets helpers (identical copy in every node that reads the sheet) ---
const S = (v) => (v == null ? '' : String(v));
const digits = (s) => S(s).replace(/\D/g, '');

// values:batchGet returns ragged rows: trailing empty cells are simply missing, and a
// blank line comes back as []. Read by header name and keep the real sheet row number.
function readTables(batch, names) {
  const out = {};
  const vrs = (batch && batch.valueRanges) || [];
  names.forEach((name, i) => {
    const vr = vrs[i] || {};
    const got = S(vr.range).replace(/^'|'?!.*$/g, '');
    if (vr.range && got && got !== name) throw new Error('Sheet order mismatch: expected ' + name + ', got ' + got);
    const rows = vr.values || [];
    const header = (rows[0] || []).map((h) => S(h).trim());
    const recs = [];
    for (let r = 1; r < rows.length; r++) {
      const row = rows[r] || [];
      if (!row.some((c) => S(c).trim() !== '')) continue;
      const rec = { __row: r + 1 };
      header.forEach((h, c) => { if (h) rec[h] = row[c] === undefined ? '' : S(row[c]).trim(); });
      recs.push(rec);
    }
    out[name] = { header, rows: recs };
  });
  return out;
}

// Staff type dates however they like, and Sheets displays them in the sheet's locale.
function parseDate(raw, order, zone) {
  const v = S(raw).trim();
  if (!v) return null;
  let d = null;
  if (/^\d{4}-\d{2}-\d{2}/.test(v)) d = DateTime.fromISO(v.slice(0, 10), { zone });
  else if (/^\d{4,5}(\.\d+)?$/.test(v)) {                          // a raw Sheets serial number
    d = DateTime.fromISO('1899-12-30', { zone }).plus({ days: Math.floor(Number(v)) });
  } else {
    const m = v.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);
    if (m) {
      const a = +m[1], b = +m[2]; let y = +m[3]; if (y < 100) y += 2000;
      const [day, month] = order === 'MDY' ? [b, a] : [a, b];
      d = DateTime.fromObject({ year: y, month, day }, { zone });
    } else {
      for (const f of ['d LLL yyyy', 'd LLLL yyyy', 'LLL d, yyyy', 'LLLL d, yyyy', 'd-LLL-yyyy']) {
        const t = DateTime.fromFormat(v, f, { zone });
        if (t.isValid) { d = t; break; }
      }
    }
  }
  return d && d.isValid ? d.startOf('day') : null;
}
const zone = CFG.timezone || 'Europe/London';
// If the sheet cannot be read, sending nothing looks exactly like nobody being due.
// Say so loudly instead - a silent day means missed vaccinations.
const batch = $input.first().json || {};
let T;
try {
  if (batch.error || !Array.isArray(batch.valueRanges)) throw new Error(S((batch.error && (batch.error.message || batch.error)) || 'no data returned'));
  T = readTables(batch, ['Owners', 'Pets', 'Appointments', 'Reminders', 'AppointmentTypes']);
  if (!T.Pets.header.length || !T.Owners.header.length) throw new Error('the Pets or Owners tab is empty - check the tab names and header row');
} catch (err) {
  return [{ json: { summary: true, due: 0, skipped: {}, bad: [], worthTelling: true, priority: 1, failed: true,
    message: 'No vaccination reminders went out today: the clinic sheet could not be read (' + S(err.message).slice(0, 200)
      + '). Nothing was sent or logged, so today\'s reminders will go out on the next run.' } }];
}
const today = DateTime.now().setZone(zone).startOf('day');
const months = Number(CFG.vaccination_interval_months) || 12;
let offsets = [14, 0, -14];
try { const o = JSON.parse(S(CFG.reminder_offsets)); if (Array.isArray(o) && o.length) offsets = o.map(Number); } catch (e) {}
const grace = Number(CFG.reminder_grace_days) || 3;           // catch up if a run was missed

const sent = new Set(T.Reminders.rows.map((r) => S(r.reminder_key)));
const vaccType = T.AppointmentTypes.rows.find((t) => /vacc/i.test(t.name) && !/^(no|false|0)$/i.test(t.active || 'yes'));
const out = []; const bad = [];
const skipped = { opted_out: 0, already_booked: 0, no_phone: 0, already_sent: 0 };

for (const p of T.Pets.rows) {
  const lastV = parseDate(p.last_vaccination, CFG.date_order, zone);
  const nextV = parseDate(p.next_vaccination_due, CFG.date_order, zone);
  if ((p.last_vaccination && !lastV) || (p.next_vaccination_due && !nextV)) bad.push(S(p.name) + ' (' + S(p.pet_id) + ', row ' + p.__row + ')');
  const due = nextV || (lastV ? lastV.plus({ months }) : null);   // luxon turns 29 Feb + 12 months into 28 Feb
  if (!due) continue;

  const open = offsets.map((off) => ({ off, from: due.minus({ days: off }) }))
    .filter((w) => today >= w.from && today < w.from.plus({ days: grace }))
    .sort((a, b) => b.from.toMillis() - a.from.toMillis());
  if (!open.length) continue;
  const w = open[0];
  const key = S(p.pet_id) + '|' + due.toISODate() + '|' + w.off;
  if (sent.has(key)) { skipped.already_sent++; continue; }

  const owner = T.Owners.rows.find((o) => digits(o.phone) && digits(o.phone) === digits(p.owner_phone));
  if (!owner || digits(owner.phone).length < 8) { skipped.no_phone++; continue; }
  if (/^(yes|true|1|y)$/i.test(S(owner.reminders_opt_out))) { skipped.opted_out++; continue; }
  const booked = T.Appointments.rows.some((a) => a.pet_id === p.pet_id && /^booked$/i.test(a.status)
    && /vacc/i.test(S(a.type)) && DateTime.fromISO(S(a.start), { zone }).isValid && DateTime.fromISO(S(a.start), { zone }) >= today);
  if (booked) { skipped.already_booked++; continue; }

  const phrase = w.off > 0 ? 'due on ' + due.toFormat('ccc d LLL')
    : w.off === 0 ? 'due today' : 'overdue - it was due on ' + due.toFormat('d LLL');
  out.push({ json: {
    reminder: true, key, pet_id: S(p.pet_id), pet_name: S(p.name), owner_phone: '+' + digits(owner.phone),
    due_date: due.toISODate(), offset_days: w.off, phone_number_id: CFG.phone_number_id,
    graph_version: CFG.graph_version || 'v25.0', token: CFG.wa_token,
    payload: {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: digits(owner.phone), type: 'template',
      template: { name: S(CFG.reminder_template), language: { code: S(CFG.template_lang) || 'en' },
        components: [
          { type: 'body', parameters: [
            { type: 'text', text: (S(owner.name).split(' ')[0] || 'there').slice(0, 60) },
            { type: 'text', text: S(p.name).slice(0, 60) },
            { type: 'text', text: phrase.slice(0, 60) }] },
          { type: 'button', sub_type: 'quick_reply', index: '0',
            parameters: [{ type: 'payload', payload: 'book:' + S(p.pet_id) + ':' + (vaccType ? S(vaccType.id) : '') }] },
          { type: 'button', sub_type: 'quick_reply', index: '1', parameters: [{ type: 'payload', payload: 'stop_reminders' }] },
        ] },
    },
  } });
}
out.push({ json: { summary: true, due: out.length, skipped, bad, priority: -1,
  worthTelling: out.length > 0 || bad.length > 0,
  message: out.length + ' vaccination reminder(s) going out today.'
    + (Object.values(skipped).some(Boolean) ? ' Skipped: ' + Object.entries(skipped).filter(([, n]) => n).map(([k, n]) => n + ' ' + k.replace(/_/g, ' ')).join(', ') + '.' : '')
    + (bad.length ? ' Dates I cannot read: ' + bad.slice(0, 10).join('; ') + (bad.length > 10 ? ' and ' + (bad.length - 10) + ' more' : '') + '.' : '') } });
return out;

// ===== Log Reminders =====
// Pairs each send result with its reminder, in order, and writes one row per reminder.
// A failed send is logged as failed, so it is retried tomorrow within the grace window.
const CFG = $('Config').first().json;
// --- Google Sheets helpers (identical copy in every node that reads the sheet) ---
const S = (v) => (v == null ? '' : String(v));
const digits = (s) => S(s).replace(/\D/g, '');

// values:batchGet returns ragged rows: trailing empty cells are simply missing, and a
// blank line comes back as []. Read by header name and keep the real sheet row number.
function readTables(batch, names) {
  const out = {};
  const vrs = (batch && batch.valueRanges) || [];
  names.forEach((name, i) => {
    const vr = vrs[i] || {};
    const got = S(vr.range).replace(/^'|'?!.*$/g, '');
    if (vr.range && got && got !== name) throw new Error('Sheet order mismatch: expected ' + name + ', got ' + got);
    const rows = vr.values || [];
    const header = (rows[0] || []).map((h) => S(h).trim());
    const recs = [];
    for (let r = 1; r < rows.length; r++) {
      const row = rows[r] || [];
      if (!row.some((c) => S(c).trim() !== '')) continue;
      const rec = { __row: r + 1 };
      header.forEach((h, c) => { if (h) rec[h] = row[c] === undefined ? '' : S(row[c]).trim(); });
      recs.push(rec);
    }
    out[name] = { header, rows: recs };
  });
  return out;
}

// Staff type dates however they like, and Sheets displays them in the sheet's locale.
function parseDate(raw, order, zone) {
  const v = S(raw).trim();
  if (!v) return null;
  let d = null;
  if (/^\d{4}-\d{2}-\d{2}/.test(v)) d = DateTime.fromISO(v.slice(0, 10), { zone });
  else if (/^\d{4,5}(\.\d+)?$/.test(v)) {                          // a raw Sheets serial number
    d = DateTime.fromISO('1899-12-30', { zone }).plus({ days: Math.floor(Number(v)) });
  } else {
    const m = v.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);
    if (m) {
      const a = +m[1], b = +m[2]; let y = +m[3]; if (y < 100) y += 2000;
      const [day, month] = order === 'MDY' ? [b, a] : [a, b];
      d = DateTime.fromObject({ year: y, month, day }, { zone });
    } else {
      for (const f of ['d LLL yyyy', 'd LLLL yyyy', 'LLL d, yyyy', 'LLLL d, yyyy', 'd-LLL-yyyy']) {
        const t = DateTime.fromFormat(v, f, { zone });
        if (t.isValid) { d = t; break; }
      }
    }
  }
  return d && d.isValid ? d.startOf('day') : null;
}
const sentItems = $('Find Due Vaccinations').all().filter((i) => i.json.reminder).map((i) => i.json);
const results = $input.all().map((i) => i.json || {});
const T = readTables($('Load Reminder Data').first().json, ['Owners', 'Pets', 'Appointments', 'Reminders', 'AppointmentTypes']);
const writes = []; const failed = [];
// One response per reminder, in order. If that is ever not true (a node-level failure can
// collapse them), record nothing as sent: a duplicate tomorrow beats a missed vaccination.
const aligned = results.length === sentItems.length;
if (!aligned) failed.push('the send step returned ' + results.length + ' results for ' + sentItems.length + ' reminders');
sentItems.forEach((r, i) => {
  const res = (aligned && results[i]) || {};
  const ok = aligned && Array.isArray(res.messages) && res.messages.length > 0 && !res.error;
  if (!ok) failed.push(r.pet_name + ': ' + S((res.error && (res.error.message || res.error.code)) || 'no response').slice(0, 80));
  // only successful sends are recorded under the dedupe key; failures get their own key
  writes.push({ op: 'append', tab: 'Reminders', record: {
    reminder_key: ok ? r.key : r.key + '|failed|' + DateTime.now().toUTC().toISO(),
    pet_id: r.pet_id, owner_phone: r.owner_phone, due_date: r.due_date, offset_days: String(r.offset_days),
    sent_at: DateTime.now().toUTC().toISO(), status: ok ? 'sent' : 'failed',
    detail: ok ? S(res.messages[0].id) : S(JSON.stringify(res.error || res)).slice(0, 300) } });
});
// Without a header row nothing can be logged, and an unlogged reminder is sent again
// tomorrow, and the day after. Staff need to hear about that.
if (!T.Reminders.header.length) {
  failed.unshift('the Reminders tab has no header row, so today\'s reminders could not be logged - they will be sent again tomorrow unless it is fixed');
}
return [{ json: { sheet_id: CFG.sheet_id, headers: { Reminders: T.Reminders.header }, writes,
  failedCount: failed.length, failedMessage: failed.length ? failed.length + ' reminder(s) failed to send: ' + failed.join('; ') : '' } }];

// ===== Split Writes =====
// Row updates go in one batchUpdate call. New rows each use values:append, because
// Google picks the next free row itself - two customers at once can never overwrite
// each other, which a computed "next row" number cannot promise.
// RAW means nothing a customer types is ever treated as a formula.
const out = [];
const S = (v) => (v == null ? '' : String(v));
const col = (n) => { let s = ''; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const q = (t) => (/^[A-Za-z0-9_]+$/.test(t) ? t : "'" + t.replace(/'/g, "''") + "'");
for (const it of $input.all()) {
  const o = it.json;
  if (!o.sheet_id) continue;
  const base = 'https://sheets.googleapis.com/v4/spreadsheets/' + encodeURIComponent(o.sheet_id);
  const updates = [];
  for (const w of (o.writes || [])) {
    const header = (o.headers || {})[w.tab] || [];
    if (!header.length) continue;
    const values = header.map((h) => (h ? S(w.record && w.record[h] !== undefined ? w.record[h] : '').slice(0, 49000) : ''));
    if (w.op === 'update' && Number(w.row) >= 2) {
      // Only touch columns that have a header. A column someone added without one
      // holds notes we know nothing about, and blanking it would lose them.
      let i = 0;
      while (i < header.length) {
        if (!header[i]) { i++; continue; }
        let j = i;
        while (j + 1 < header.length && header[j + 1]) j++;
        updates.push({ range: q(w.tab) + '!' + col(i + 1) + w.row + ':' + col(j + 1) + w.row, values: [values.slice(i, j + 1)] });
        i = j + 1;
      }
    } else if (w.op === 'append') {
      out.push({ json: { method: 'POST',
        url: base + '/values/' + encodeURIComponent(q(w.tab) + '!A1') + ':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS',
        body: { values: [values] }, tab: w.tab, op: 'append' } });
    }
  }
  if (updates.length) out.unshift({ json: { method: 'POST', url: base + '/values:batchUpdate',
    body: { valueInputOption: 'RAW', data: updates }, tab: updates.map((u) => u.range.split('!')[0]).join(','), op: 'update' } });
}
return out;
